mapper.select:
SELECT 
FROM chat_message
WHERE session_id = #{sessionId}
ORDER BY seq ASC
LIMIT -1 OFFSET #{offset}

mapper.update:
UPDATE chat_message
SET content_json = #{json}, content_encoding = NULL, content_blob = NULL
WHERE id = #{id}

UPDATE chat_message
SET hidden = #{hidden}
WHERE session_id = #{sessionId} AND seq >= #{fromSeq} AND seq <= #{toSeq} AND hidden = #{prevHidden}
